bool AreAnagrams(string s1, string s2)
{
    if (s1.Length != s2.Length)
        return false;

    int[] a = new int[256];
    int n = s1.Length;
    for (int i = 0; i < n; i++)
    {
        int c1 = (int)s1[i];
        int c2 = (int)s2[i];

        a[c1]++;
        a[c2]--;
    }

    for (int i = 0; i < 256; i++)
    {
        if (a[i] != 0)
            return false;
    }

    return true;
}

function reverseArrayInPlace(nums) {
    let left = 0;
    let right = nums.length - 1;

    while (left < right) {
        let temp = nums[left];
        nums[left] = nums[right];
        nums[right] = temp;

        left++;
        right--;
    }
    return nums;
}

