Calculate the LCM (Least Common Multiple) of two integers.

int x = 15;
int y = 10;

def lcm(x, y): 
    if x > y:
        greater = x 
    else:
        greater = y 
    while(True): 
        if((greater % x == 0) and (greater % y == 0)): 
            lcm = greater 
            break
        greater += 1 
    return lcm 

